/**
 * i18n resources — English (source of truth) + Arabic.
 *
 * Flat, dot-namespaced keys keep lookups O(1), make the completeness audit
 * trivial (both objects are flat maps), and let the fallback chain be a simple
 * `en[key] ?? key`. Nested objects were rejected: they complicate the "missing
 * key" fallback and buy nothing for an app of this size.
 *
 * INTERPOLATION: placeholders use `{name}` and are substituted by `t()` in
 * src/lib/i18n/index.ts. Both languages MUST use the SAME placeholder names —
 * a test enforces this (tests/i18nLocalization.test.cjs).
 *
 * DO NOT translate: product names (MedAcademy), user-provided content, course
 * titles, emails, URLs, API field names, technical identifiers, or payload
 * values. Those are data, not UI copy.
 */

export type TranslationDict = Record<string, string>;

