  'terms.s3h': '3. استخدام المحتوى',
  'terms.s3b':
    'جميع محتويات الدورات — بما في ذلك الفيديوهات وملفات PDF والمواد — محمية بحقوق النشر، ولا يجوز تسجيلها أو توزيعها أو إعادة إنتاجها بأي شكل. وتُضمَّن علامات مائية جنائية في كل المحتوى المتدفق لتحديد المشاركة غير المصرّح بها.',
  'terms.s4h': '4. الاشتراكات والوصول',
  'terms.s4b':
    'يُمنح الوصول إلى الدورات من خلال التسجيل بواسطة الطبيب أو مسؤول المنصة. والوصول شخصي وغير قابل للنقل. ولا تُتيح الاشتراكات المكتملة أو المنتهية للمستخدم استرداد أي مبلغ إلا إذا ذُكر ذلك صراحةً.',
  'terms.s5h': '5. السلوك المحظور',
  'terms.s5b':
    'توافق على عدم محاولة التحايل على إجراءات الأمان، أو استخدام برامج تسجيل الشاشة أثناء تشغيل المحتوى، أو استغلال أي ثغرات تقنية. وقد تؤدي المخالفات إلى إنهاء الحساب فورًا.',
  'terms.s6h': '6. الملكية الفكرية',
  'terms.s6b':
    'جميع المحتويات والعلامات التجارية والهوية البصرية على منصة MedAcademy هي ملكية حصرية للمنصة ولمدرّبيها. ويُعدّ أي استخدام غير مصرّح به اعتداءً على حقوق الملكية الفكرية.',
  'terms.s7h': '7. إخلاء المسؤولية عن الضمانات',
  'terms.s7b':
    'تُقدَّم المنصة "كما هي" دون أي ضمانات من أي نوع. ولا نضمن استمرار الوصول دون انقطاع، ولا نتحمل المسؤولية عن دقة المحتوى بما يتجاوز معاييرنا التحريرية المعقولة.',
  'terms.s8h': '8. التعديلات',
