    'نجمع المعلومات التي تقدّمها عند التسجيل (الاسم والبريد الإلكتروني ورقم الهاتف)، والمعلومات الأكاديمية (الجامعة والكلية والمستوى الدراسي)، ومعلومات الجهاز اللازمة لتطبيق إجراءات الأمان. كما نجمع بيانات التفاعل مع المحتوى مثل تقدّم المشاهدة وإتمام الدروس.',
