/** Every supported UI locale. English is the fallback / source of truth. */
export const LOCALES = ['en', 'ar'] as const;
export type Locale = (typeof LOCALES)[number];
export const DEFAULT_LOCALE: Locale = 'en';

export const RESOURCES: Record<Locale, TranslationDict> = { en, ar };
